        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
    if ty is not None:
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1

    # If no target-derived movement, try to move toward center of map
    if dx == 0 and dy == 0:
